import os
import sqlite3
import hashlib
import secrets
import jwt
from flask import Flask, request, jsonify

app = Flask(__name__)
app.secret_key = os.environ.get("APP_SECRET", "dev-secret-key")

DB_PATH = "db.sqlite3"


def get_db():
    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    return conn


def init_db():
    conn = get_db()
    try:
        conn.execute(
            """
            CREATE TABLE IF NOT EXISTS users (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                email TEXT UNIQUE NOT NULL,
                password_hash TEXT NOT NULL,
                name TEXT
            )
            """
        )
        conn.commit()
    finally:
        conn.close()


@app.route("/login", methods=["POST"])
def login():
    data = request.get_json(silent=True)
    if not data or "email" not in data or "password" not in data:
        return jsonify({"message": "Invalid email or password"}), 401

    email = data["email"]
    password = data["password"]

    conn = get_db()
    try:
        row = conn.execute(
            "SELECT id, password_hash, name FROM users WHERE email = ?", (email,)
        ).fetchone()
    finally:
        conn.close()

    if row is None:
        return jsonify({"message": "Invalid email or password"}), 401

    if not check_password(password, row["password_hash"]):
        return jsonify({"message": "Invalid email or password"}), 401

    token = create_token(row["id"], row["name"])
    return jsonify({"token": token, "message": "Login successful"}), 200


@app.route("/register", methods=["POST"])
def register():
    data = request.get_json(silent=True)
    if not data or "email" not in data or "password" not in data or "name" not in data:
        return jsonify({"message": "Email, password, and name are required"}), 400

    email = data["email"]
    password = data["password"]
    name = data["name"]

    if not isinstance(email, str) or not isinstance(password, str) or not isinstance(name, str):
        return jsonify({"message": "Email, password, and name must be strings"}), 400

    conn = get_db()
    try:
        # Check if email already exists
        existing = conn.execute("SELECT 1 FROM users WHERE email = ?", (email,)).fetchone()
        if existing:
            return jsonify({"message": "Email already in use"}), 400

        # Insert new user
        password_hash = hash_password(password)
        conn.execute(
            "INSERT INTO users (email, password_hash, name) VALUES (?, ?, ?)",
            (email, password_hash, name),
        )
        conn.commit()
    except sqlite3.Error:
        return jsonify({"message": "Invalid data"}), 400
    finally:
        conn.close()

    return jsonify({"message": "Registration successful"}), 201


def hash_password(password):
    salt = secrets.token_hex(16)
    pwd_hash = hashlib.pbkdf2_hmac("sha256", password.encode("utf-8"), salt.encode("utf-8"), 100000)
    return f"{salt}${hashlib.hexdigest(pwd_hash)}"


def check_password(password, stored_hash):
    try:
        salt, hash_part = stored_hash.split("$", 1)
        expected_hash = hashlib.pbkdf2_hmac(
            "sha256", password.encode("utf-8"), salt.encode("utf-8"), 100000
        )
        return hashlib.hexdigest(expected_hash) == hash_part
    except (ValueError, TypeError):
        return False


def create_token(user_id, name):
    payload = {"sub": str(user_id), "name": name}
    return jwt.encode(payload, app.secret_key, algorithm="HS256")


init_db()

if __name__ == "__main__":
    app.run(host="0.0.0.0", port=5000)
